<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_role('student');
$statement = db()->prepare("SELECT q.id, q.title, q.description, q.pass_percentage, c.id AS course_id, c.title AS course_title, l.title AS lesson_title FROM quizzes q INNER JOIN lessons l ON l.id=q.lesson_id INNER JOIN courses c ON c.id=l.course_id INNER JOIN enrollments e ON e.course_id=c.id AND e.user_id=:user_id WHERE q.status='published' AND l.status='published' AND c.status='published' ORDER BY c.title, l.sort_order, q.id"); $statement->execute(['user_id'=>current_user()['id']]); $quizzes=$statement->fetchAll();
$pageTitle='Quizzes'; require __DIR__ . '/../includes/header.php';
?>
<div class="py-4"><div class="mb-4"><h1 class="h2 fw-bold">Information Technology Quizzes</h1><p class="text-secondary">Complete quizzes from your enrolled courses.</p></div><div class="row g-4"><?php if (!$quizzes): ?><div class="col-12"><div class="card p-5 text-center text-secondary">No quizzes are available. Enroll in a course to see its quizzes.</div></div><?php endif; ?><?php foreach ($quizzes as $quiz): ?><div class="col-md-6 col-xl-4"><div class="card feature-card h-100"><div class="card-body p-4 d-flex flex-column"><span class="badge text-bg-light align-self-start mb-3"><?= e($quiz['course_title']) ?></span><h2 class="h5"><?= e($quiz['title']) ?></h2><p class="small text-secondary"><?= e($quiz['lesson_title']) ?></p><p class="text-secondary flex-grow-1"><?= e($quiz['description'] ?? '') ?></p><p class="small text-secondary">Pass mark: <?= e((string)$quiz['pass_percentage']) ?>%</p><a class="btn btn-primary mt-auto" href="<?= e(app_url('student/quiz.php?id=' . $quiz['id'])) ?>">Start quiz</a></div></div></div><?php endforeach; ?></div></div>
<?php require __DIR__ . '/../includes/footer.php'; ?>
